LANG_NAMES = {"en": "English", "es": "Español", "th": "ไทย", "fr": "Français", "de": "Deutsch", "it": "Italiano",
              "pt": "Português", "nl": "Nederlands", "ja": "日本語", "zh": "中文", "vi": "Tiếng Việt"}


def L(lang: str, key: str, **kw) -> str:
    s = LABELS.get(lang.split("-")[0], {}).get(key) or LABELS["en"][key]
    return s.format(**kw)


def mmss(t: float) -> str:
    return f"{int(t // 60):02d}:{int(t % 60):02d}"
